using System;
using System.IO;
using System.Linq;
using KMA.Gameplay.UI;
using UnityEditor;
using UnityEngine;
namespace KMA.EditorTools
{
    public static class GameplayDialogueContentBuilder
    {
        public const string Path="Assets/_Project/Resources/Journey/GameplayDialogues.asset";
        public static void Build()
        {
            AssetDatabase.Refresh();
            const string iconPath="Assets/_Project/Art/UI/Dialogue/PointingHandRight.png";
            var importer=(TextureImporter)AssetImporter.GetAtPath(iconPath);
            if(importer==null)throw new InvalidOperationException("Missing "+iconPath);
            importer.textureType=TextureImporterType.Sprite;importer.alphaIsTransparency=true;
            importer.mipmapEnabled=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();
            Sprite icon=AssetDatabase.LoadAssetAtPath<Sprite>(iconPath);
            var library=AssetDatabase.LoadAssetAtPath<GameplayDialogueLibrary>(Path);
            if(library==null){library=ScriptableObject.CreateInstance<GameplayDialogueLibrary>();AssetDatabase.CreateAsset(library,Path);}
            library.SetContent(new GameplayDialogueEvent[]
            {
                new GameplayDialogueEvent { Id="chess.start", ReactionGroup="chess.start", Priority=DialoguePriority.Technical, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Tối đa {maxMoves} nước, {timeSeconds} giây. Không chiếu hết được thì chịu khó ngồi làm lại.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "handsOnHips") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="chess.mistake1", ReactionGroup="chess.mistake1", Priority=DialoguePriority.Error, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Đi thế này thì cậu định chiếu hết kiểu gì? Còn {movesRemaining} nước, nghĩ cho kỹ.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "whistle0"), CharacterArt.Load(CharacterArt.Boss, "whistle1"), CharacterArt.Load(CharacterArt.Boss, "strictLook") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="chess.mistake2", ReactionGroup="chess.mistake2", Priority=DialoguePriority.Error, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Lại đi như thế. Cậu định ngồi đây đến lúc khóa sau vào học à?", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "whistle0"), CharacterArt.Load(CharacterArt.Boss, "whistle1"), CharacterArt.Load(CharacterArt.Boss, "angry") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="chess.solved", ReactionGroup="chess.solved", Priority=DialoguePriority.Result, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Tạm được. Bài này qua.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "scoreWrite") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="chess.timeout", ReactionGroup="chess.timeout", Priority=DialoguePriority.Result, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Hết giờ. Ngồi nhìn bàn cờ không làm xuất hiện nước chiếu hết đâu.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "handsOnHips") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="chess.failed", ReactionGroup="chess.failed", Priority=DialoguePriority.Result, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Chưa đạt. Ngồi xuống làm lại, đừng tưởng cứ đi hết nước là được về.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "angry") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="chess.hint1", ReactionGroup="chess.hint1", Priority=DialoguePriority.Technical, MaximumPlays=0, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Còn đường chiếu hết trong {mateDistance} nước. Nhìn các nước chiếu, đừng chỉ ngồi nhìn quân.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "taunt") }, DurationSeconds=8f } } },
                new GameplayDialogueEvent { Id="chess.hint2", ReactionGroup="chess.hint2", Priority=DialoguePriority.Technical, MaximumPlays=0, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Nhìn quân {piece} ở {from}. Cậu bỏ qua quân đó rồi.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "command") }, DurationSeconds=8f } } },
                new GameplayDialogueEvent { Id="chess.hint3", ReactionGroup="chess.hint3", Priority=DialoguePriority.Technical, MaximumPlays=0, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Đi {piece} từ {from} đến {to}{promotionSuffix}. Tôi chỉ đến thế này rồi, đừng bảo là chưa biết đi đâu.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "command") }, DurationSeconds=8f } } },
                new GameplayDialogueEvent { Id="sp.learn.start", ReactionGroup="sp.learn.start", Priority=DialoguePriority.Technical, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Mới khởi động mà chân tớ đã run rồi.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "think") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Vào vị trí. Nghe còi thì chạy, đừng để tôi phải gọi từng cậu.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "command") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="sp.learn.wrong", ReactionGroup="sp.learn.wrong", Priority=DialoguePriority.Error, MaximumPlays=2, CooldownSeconds=10f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Tớ lại hụt nhịp rồi...", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "disappointed") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Hai chân chạy cho đều. Định cứ loạng choạng thế đến hết buổi à?", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "taunt") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="sp.learn.done", ReactionGroup="sp.learn.done", Priority=DialoguePriority.Result, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Hết hồn. Tí nữa tớ tưởng không qua.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "happy") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Tạm được. Vào bài luyện.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "scoreWrite") }, DurationSeconds=1.2f } } },
                new GameplayDialogueEvent { Id="sp.practice.start", ReactionGroup="sp.practice.start", Priority=DialoguePriority.Technical, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Cô bắt chạy nữa à? Tớ vẫn chưa hết mệt.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "fear") }, DurationSeconds=2.5f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Chưa đến đích thì chưa được nghỉ. Giữ nhịp hai chân, chạy cho hết bài.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "handsOnHips") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="sp.practice.break", ReactionGroup="sp.practice.break", Priority=DialoguePriority.Error, MaximumPlays=2, CooldownSeconds=10f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Tớ lại hụt nhịp rồi.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "disappointed") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Không giữ được nhịp thì đến bài thi cậu định làm gì?", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "command") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="sp.practice.done", ReactionGroup="sp.practice.done", Priority=DialoguePriority.Result, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="May quá, em kịp rồi.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "happy") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Tạm được. Vào thi vẫn chạy thế này thì chưa chắc qua đâu.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "scoreWrite") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="sp.exam.start", ReactionGroup="sp.exam.start", Priority=DialoguePriority.Technical, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Dạ... cô cho em đứng vững đã ạ.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "fear") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Vào vị trí. Khi nghe còi hiệu lệnh, tất cả chạy.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "whistle0"), CharacterArt.Load(CharacterArt.Boss, "whistle1"), CharacterArt.Load(CharacterArt.Boss, "strictLook") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="sp.exam.lowtime", ReactionGroup="sp.exam.lowtime", Priority=DialoguePriority.Technical, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Vẫn chưa tới... sắp hết giờ rồi.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "fear") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Vạch đích ngay trước mặt. Không chạy được nữa thì học lại với khóa sau.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "handsOnHips") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="sp.exam.stumble", ReactionGroup="sp.exam.stumble", Priority=DialoguePriority.Error, MaximumPlays=2, CooldownSeconds=10f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Ui da!", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "hurt") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Giữ thăng bằng, chạy tiếp. Tôi chưa bảo dừng.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "command") }, DurationSeconds=1.2f } } },
                new GameplayDialogueEvent { Id="vb.learn.start", ReactionGroup="vb.learn.start", Priority=DialoguePriority.Technical, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Tớ sợ bóng đập vào mặt quá.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "fear") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Đứng vào vị trí. Bóng sang thì đỡ, không ai đỡ hộ cậu đâu.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "command") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="vb.learn.miss", ReactionGroup="vb.learn.miss", Priority=DialoguePriority.Error, MaximumPlays=2, CooldownSeconds=10f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Hết hồn, tớ chưa kịp tới...", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "disappointed") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Bóng rơi ngay trước mặt mà cậu vẫn đứng nhìn. Di chuyển sớm lên.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "taunt") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="vb.learn.done", ReactionGroup="vb.learn.done", Priority=DialoguePriority.Result, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Tớ đỡ được rồi... may quá.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "happy") }, DurationSeconds=1.2f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Tạm được. Đến bài luyện.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "scoreWrite") }, DurationSeconds=1.2f } } },
                new GameplayDialogueEvent { Id="vb.practice.start", ReactionGroup="vb.practice.start", Priority=DialoguePriority.Technical, MaximumPlays=1, CooldownSeconds=0f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Tay tớ vẫn còn run. Không biết đỡ nổi không.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "think") }, DurationSeconds=2.5f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Đỡ cho chắc rồi đánh qua lưới. Đứng nhìn bóng thì chỉ có nợ môn.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "handsOnHips") }, DurationSeconds=2.5f } } },
                new GameplayDialogueEvent { Id="vb.practice.badtime", ReactionGroup="vb.practice.badtime", Priority=DialoguePriority.Error, MaximumPlays=2, CooldownSeconds=10f, Lines=new[] { new GameplayDialogueLine { Speaker=DialogueSpeaker.Student, Text="Tớ đỡ lệch rồi.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Hero, "disappointed") }, DurationSeconds=2.5f }, new GameplayDialogueLine { Speaker=DialogueSpeaker.Teacher, Text="Chờ bóng vào tầm rồi hãy đánh.", Poses=new Sprite[] { CharacterArt.Load(CharacterArt.Boss, "command") }, DurationSeconds=2.5f } } },
